-- Auto-generated seed from mock data
-- Run after 001_initial_schema.sql

-- apps
on conflict (id) do update set
  app_store_id=excluded.app_store_id,
  name=excluded.name, developer=excluded.developer,
  category=excluded.category, icon_url=excluded.icon_url,
  description=excluded.description, updated_at=now();

-- Resolve any stale app_store_id duplicates introduced by bad mock data.
-- If a row with the same app_store_id already exists under a different id,
-- update it in place rather than erroring.
select id, app_store_id, name, developer, category, icon_url, description
from apps where id = 'craft'
on conflict (app_store_id) do update set
  id=excluded.id,
  name=excluded.name, developer=excluded.developer,
  category=excluded.category, icon_url=excluded.icon_url,
  description=excluded.description, updated_at=now();

-- countries
on conflict (code) do update set
  name=excluded.name, currency=excluded.currency, flag=excluded.flag;

-- exchange_rates
on conflict (currency) do update set
  rate_to_usd=excluded.rate_to_usd, rate_to_cny=excluded.rate_to_cny, fetched_at=now();
